import json,numpy as np,cv2,os
CAM=json.load(open('materials/cameras.json'))
OP=json.load(open('materials/object_points.json'))

def K(clip):
    c=CAM[clip]; return np.array([[c['fx'],0,c['cx']],[0,c['fy'],c['cy']],[0,0,1]])

def project(clip,R,t):
    P=np.array(OP[clip]) @ R.T + t
    z=P[:,2:3]
    uv=(P[:,:2]/z)*[CAM[clip]['fx'],CAM[clip]['fy']]+[CAM[clip]['cx'],CAM[clip]['cy']]
    return uv, P[:,2]

def overlay(clip,frame,R,t,out):
    img=cv2.imread(f'frames/{clip}/f{frame:05d}.png')
    uv,z=project(clip,R,t)
    for (u,v),zz in zip(uv,z):
        if zz>0 and 0<=u<1024 and 0<=v<1024:
            cv2.circle(img,(int(u),int(v)),1,(0,0,255),-1)
    # draw axes at origin
    for vec,col in [((0.05,0,0),(255,0,0)),((0,0.05,0),(0,255,0)),((0,0,0.05),(0,0,255))]:
        pts=np.array([[0,0,0],vec])@R.T+t
        uvax=(pts[:,:2]/pts[:,2:3])*[CAM[clip]['fx'],CAM[clip]['fy']]+[CAM[clip]['cx'],CAM[clip]['cy']]
        cv2.line(img,tuple(uvax[0].astype(int)),tuple(uvax[1].astype(int)),col,2)
    cv2.imwrite(out,img)

def quat_from_R(R):
    m=R; t=np.trace(m)
    if t>0:
        s=np.sqrt(t+1)*2; w=0.25*s; x=(m[2,1]-m[1,2])/s; y=(m[0,2]-m[2,0])/s; z=(m[1,0]-m[0,1])/s
    elif m[0,0]>m[1,1] and m[0,0]>m[2,2]:
        s=np.sqrt(1+m[0,0]-m[1,1]-m[2,2])*2; w=(m[2,1]-m[1,2])/s; x=0.25*s; y=(m[0,1]+m[1,0])/s; z=(m[0,2]+m[2,0])/s
    elif m[1,1]>m[2,2]:
        s=np.sqrt(1+m[1,1]-m[0,0]-m[2,2])*2; w=(m[0,2]-m[2,0])/s; x=(m[0,1]+m[1,0])/s; y=0.25*s; z=(m[1,2]+m[2,1])/s
    else:
        s=np.sqrt(1+m[2,2]-m[0,0]-m[1,1])*2; w=(m[1,0]-m[0,1])/s; x=(m[0,2]+m[2,0])/s; y=(m[1,2]+m[2,1])/s; z=0.25*s
    q=np.array([w,x,y,z]); return q/np.linalg.norm(q)

def R_from_quat(q):
    w,x,y,z=q/np.linalg.norm(q)
    return np.array([[1-2*(y*y+z*z),2*(x*y-z*w),2*(x*z+y*w)],
                     [2*(x*y+z*w),1-2*(x*x+z*z),2*(y*z-x*w)],
                     [2*(x*z-y*w),2*(y*z+x*w),1-2*(x*x+y*y)]])

def rotx(a): c,s=np.cos(a),np.sin(a);return np.array([[1,0,0],[0,c,-s],[0,s,c]])
def roty(a): c,s=np.cos(a),np.sin(a);return np.array([[c,0,s],[0,1,0],[-s,0,c]])
def rotz(a): c,s=np.cos(a),np.sin(a);return np.array([[c,-s,0],[s,c,0],[0,0,1]])

def centroid(clip): return np.array(OP[clip]).mean(0)
